import{_ as s,l as i,o as e,c as l,v as t,p as n,x as r,d,i as A,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"SAML","description":"","frontmatter":{"title":"SAML","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/saml.md","filePath":"cs/saml.md","lastUpdated":1789023840000}'),c={name:"cs/saml.md"};function S(p,a,E,u,m,_){const o=i("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="saml" tabindex="-1">SAML <a class="header-anchor" href="#saml" aria-label="Permalink to &quot;SAML&quot;">​</a></h1><div class="epigraph"><p>SAML 用 XML 断言在身份提供者与服务提供者之间搬家。签名包络、受众、时间窗与「谁解析 XML」决定断言是否可被换皮。</p><footer>—— OASIS SAML 2.0；对照 RFC 7522 等承载轮廓；Gross 与 Pfitzmann 对联邦的讨论</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/oauth-attack-surface">OAuth</a>是 JSON/REST 联邦的近亲。缺口是<strong>企业 SSO 仍大量走 SAML</strong>：浏览器 POST 断言。本课收验证合同，不给 XML 包装攻击的操作步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>签名不覆盖被解析的那块、允许外部实体、受众为空、时钟窗过大、SP 不验 <code>InResponseTo</code>。缺口是 XML 安全与断言语义，不是再讲联邦单点登录的商业故事。</p><h3 id="与-oidc-并存" tabindex="-1">与 OIDC 并存 <a class="header-anchor" href="#与-oidc-并存" aria-label="Permalink to &quot;与 OIDC 并存&quot;">​</a></h3><p>同一组织可两套 IdP。应用应钉一种验证库，不要「有断言就信」。</p><p><span class="marginnote">SAML 2.0 Core。XML 数字签名与包装是经典失败模式——只陈述「验签树必须等于解析树」。本课禁止利用指导。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画 SP 发起 SSO：Redirect 到 IdP，回来 POST 断言。列出必验：签名、Issuer、Audience、条件时间、Subject。对照 JWT：同是声明，编码不同。</p>',12)),(e(),n(h,null,{default:r(()=>[A(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20SP%5B%22%E6%9C%8D%E5%8A%A1%E6%8F%90%E4%BE%9B%E8%80%85%22%5D%20--%3E%20IDP%5B%22%E8%BA%AB%E4%BB%BD%E6%8F%90%E4%BE%9B%E8%80%85%22%5D%0A%20%20IDP%20--%3E%20ASS%5B%22%E5%B8%A6%E7%AD%BE%E6%96%AD%E8%A8%80%22%5D%0A%20%20ASS%20--%3E%20V%5B%22%E9%AA%8C%E7%AD%BE%E6%A0%91%3D%E8%A7%A3%E6%9E%90%E6%A0%91%22%5D%0A%20%20V%20--%3E%20SESS%5B%22%E5%BB%BA%20SP%20%E4%BC%9A%E8%AF%9D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>联邦把口令从 SP 拿走，把 TCB 换成 IdP 与 XML 栈。下一课 WebAuthn：把密钥放到认证器，减少共享口令与断言解析面。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部 Bindings。WebAuthn/FIDO2 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OAuth 之后，SAML 是 XML 断言联邦。</li><li>签名覆盖必须对准实际解析的断言。</li><li>受众与时间窗不可空转。</li><li>下一课 WebAuthn / FIDO2。</li><li>出处：OASIS SAML 2.0；对照 OWASP 对 SAML 的讨论；Anderson。</li></ul>',8))])}const f=s(c,[["render",S]]);export{B as __pageData,f as default};
